const TOOL_LIBRARY=['CNMG120408','CNMG120404','WNMG080408','16ER 1.25 ISO','16IR 1.25 ISO','Фреза Ø8 4 зуба','Сверло Ø6','Метчик M8×1.25','Отрезной резец 3 мм'];
function openSupport(name){const data=SUPPORT_DATA[name];if(!data)return;let modal=document.getElementById('supportModal');if(!modal){modal=document.createElement('div');modal.id='supportModal';modal.className='support-modal';modal.innerHTML='<div class="support-dialog"><div class="support-head"><h2 id="supportTitle"></h2><button id="supportClose" class="ghost">×</button></div><div id="supportBody"></div></div>';document.body.appendChild(modal);modal.querySelector('#supportClose').onclick=()=>modal.classList.remove('open');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')}}modal.querySelector('#supportTitle').textContent=data.title;modal.querySelector('#supportBody').innerHTML=data.html;modal.classList.add('open');bindSupport(name)}
async function bindDigitalTwin(){
  const status=document.getElementById('dtStatus'),profile=document.getElementById('dtProfile'),missing=document.getElementById('dtMissing'),search=document.getElementById('dtSearch'),manualSel=document.getElementById('dtManual'),translateManual=document.getElementById('dtTranslateManual'),results=document.getElementById('dtResults'),searchStatus=document.getElementById('dtSearchStatus'),photos=document.getElementById('dtPhotos'),photoCat=document.getElementById('dtPhotoCategory'),pagesInput=document.getElementById('dtPages');
  const parsePages=value=>{const set=new Set();String(value||'').split(',').forEach(part=>{const m=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)return;const a=+m[1],b=+(m[2]||m[1]);for(let p=Math.min(a,b);p<=Math.max(a,b)&&set.size<40;p++)set.add(p)});return [...set].sort((a,b)=>a-b)};
  const fetchJson=async url=>{const r=await fetch(url),j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка загрузки');return j};
  const loadPhotos=async()=>{const j=await fetchJson(`/api/digital-twin/photos?category=${encodeURIComponent(photoCat.value||'all')}`);photos.innerHTML=j.items.map(x=>`<figure><img src="${esc(x.url)}" loading="lazy"><figcaption><b>${esc(x.id)}</b><span>${esc(x.label)}</span></figcaption></figure>`).join('')||'<div class="manager-empty">Фотографий нет</div>'};
  try{const [sum,manuals]=await Promise.all([fetchJson('/api/digital-twin/summary'),fetchJson('/api/digital-twin/manuals')]);const p=sum.profile||{},c=p.control||{},cfg=p.configuration||{};status.className='check-card good';status.innerHTML=`<b>Двойник загружен · ${sum.completeness_percent}% подтверждения</b><span>${sum.counts.photos} фото · ${sum.counts.manuals} мануалов · ${sum.counts.manual_pages.toLocaleString('ru-RU')} страниц</span>`;profile.innerHTML=`<div class="dt-hero"><strong>${esc(p.name)}</strong><span>${esc(c.family)} ${esc(c.variant)} · ${esc(c.cnc_software)}</span></div><div class="dt-facts"><span><b>X/Y/Z</b> подтверждены</span><span><b>C</b> предусмотрена, лимиты неизвестны</span><span><b>Револьвер</b> ${esc(cfg.turret?.positions||'—')} позиций</span><span><b>Tailstock Jog</b> ${cfg.tailstock?.jog_control?'есть':'нет данных'}</span><span><b>PLC</b> ${esc(p.plc?.project||'—')}</span><span><b>MPF</b> заблокирован до паспорта</span></div>`;missing.innerHTML=(p.not_confirmed||[]).map(x=>`<span>⚠ ${esc(x)}</span>`).join('');const opts=manuals.items.map(m=>`<option value="${esc(m.id)}">${esc(m.title)} · ${esc(m.edition)}</option>`).join('');manualSel.insertAdjacentHTML('beforeend',opts);translateManual.innerHTML=opts;await loadPhotos()}catch(e){status.className='check-card warning';status.textContent=e.message}
  let timer;const runSearch=async()=>{const q=search.value.trim();if(!q){results.innerHTML='';searchStatus.textContent='Введите запрос';return}searchStatus.textContent='Поиск…';try{const j=await fetchJson(`/api/digital-twin/search?q=${encodeURIComponent(q)}&manual_id=${encodeURIComponent(manualSel.value||'')}&limit=20`);searchStatus.textContent=`Найдено страниц: ${j.items.length}`;results.innerHTML=j.items.map(x=>`<article class="dt-result"><div><b>${esc(x.manual_title)}</b><span>стр. ${x.page} · ${esc(x.software||'')} · ${esc(x.trust||'')}</span></div><p>${esc(x.snippet||'').replaceAll('&lt;mark&gt;','<mark>').replaceAll('&lt;/mark&gt;','</mark>')}</p><button class="ghost small" data-translate-page="${x.page}" data-manual-id="${esc(x.manual_id)}">ПЕРЕВЕСТИ СТРАНИЦУ</button><div class="dt-translation" id="dtTr-${esc(x.manual_id)}-${x.page}"></div></article>`).join('')||'<div class="manager-empty">Ничего не найдено</div>';results.querySelectorAll('[data-translate-page]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;btn.textContent='ПЕРЕВОД…';const body={manual_id:btn.dataset.manualId,pages:[+btn.dataset.translatePage]};try{const r=await fetch('/api/digital-twin/translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка перевода');document.getElementById(`dtTr-${btn.dataset.manualId}-${btn.dataset.translatePage}`).innerHTML=`<div class="check-card good"><b>Русский перевод</b><span>${esc(j.items?.[0]?.translation||'')}</span></div>`;btn.textContent='ГОТОВО'}catch(e){btn.disabled=false;btn.textContent='ПОВТОРИТЬ';alert(e.message)}})}catch(e){searchStatus.textContent=e.message}};search.oninput=()=>{clearTimeout(timer);timer=setTimeout(runSearch,220)};manualSel.onchange=runSearch;photoCat.onchange=loadPhotos;
  document.getElementById('dtTranslateBtn').onclick=async()=>{const pages=parsePages(pagesInput.value);if(!pages.length)return alert('Введите страницы, например 13-18');if(pages.length>8)return alert('За один запрос можно перевести не более 8 страниц');const btn=document.getElementById('dtTranslateBtn');btn.disabled=true;btn.textContent='ПЕРЕВОД…';try{const r=await fetch('/api/digital-twin/translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({manual_id:translateManual.value,pages})}),j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка перевода');alert(`Переведено/загружено из кэша: ${j.count} стр.`);btn.textContent='ГОТОВО'}catch(e){alert(e.message);btn.textContent='ПЕРЕВЕСТИ'}finally{btn.disabled=false}};
  document.getElementById('dtExportBtn').onclick=async()=>{const pages=parsePages(pagesInput.value);const r=await fetch('/api/digital-twin/export-translation-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({manual_id:translateManual.value,pages})});if(!r.ok){const j=await r.json();return alert(j.detail||'Ошибка экспорта')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${translateManual.value}_RU.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
}
function bindSupport(name){if(name==='digitalTwin'){bindDigitalTwin();return}if(name==='knowledge'){const search=document.getElementById('kbSearch'),category=document.getElementById('kbCategory'),results=document.getElementById('kbResults'),status=document.getElementById('kbStatus'),machine=document.getElementById('kbMachine'),docs=document.getElementById('kbDocuments');let timer=null;const trustLabel=value=>({confirmed_from_machine:'подтверждено станком',primary_exact_v495:'точно для V4.95',workflow_supplement_v525:'дополнение V5.25',unverified_oem:'OEM не подтверждено',service_only_do_not_execute:'сервисный код — не выполнять',safety_rule:'правило безопасности',project_policy:'политика проекта'}[value]||value||'справочно');const drawItems=items=>{results.innerHTML=items.length?items.map(item=>{const source=item.source||{},pages=Array.isArray(source.pages)&&source.pages.length?' · стр. '+source.pages.join(', '):'',sourceName=source.document||source.ref||source.type||'локальная база';return `<article class="kb-item ${item.kind==='m_code'&&item.trust!=='common_verify_on_machine'?'kb-danger':''}"><div class="kb-item-head"><b>${esc(item.title)}</b><span>${esc(trustLabel(item.trust))}</span></div><p>${esc(item.summary||'')}</p><small>${esc(sourceName+pages)} · ${esc(item.safety||'')}</small></article>`}).join(''):'<div class="manager-empty">По запросу ничего не найдено</div>'};const run=async()=>{status.textContent='Поиск…';const q=encodeURIComponent(search.value||''),cat=encodeURIComponent(category.value||'all');try{const r=await fetch(`/api/knowledge/search?q=${q}&category=${cat}&limit=30`),j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка поиска');drawItems(j.items||[]);status.className='check-card good';status.textContent=`Найдено: ${(j.items||[]).length} · профиль ${j.machine_profile_id||'—'}`}catch(error){status.className='check-card warning';status.textContent=error.message}};Promise.all([fetch('/api/knowledge/summary').then(async r=>{const j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка загрузки профиля');return j}),fetch('/api/knowledge/documents').then(async r=>{const j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка загрузки источников');return j})]).then(([summary,documentData])=>{const m=summary.machine||{},c=m.control||{},caps=m.confirmed_capabilities||{},loaded=Boolean(summary.ok&&summary.counts?.total_entries&&m.profile_id);if(!loaded){machine.innerHTML='<div class="check-card warning"><b>База не загружена</b><span>Профиль станка и источники отсутствуют на сервере. Машинно-зависимые подсказки нельзя считать проверенными.</span></div>';docs.innerHTML='<div class="manager-empty">Источники не загружены</div>';status.className='check-card warning';status.textContent='Ошибка развёртывания: локальная база отсутствует';results.innerHTML='<div class="manager-empty">Поиск отключён до загрузки базы</div>';return}machine.innerHTML=`<div class="check-card good"><b>${esc(m.name)}</b><span>${esc(c.family)} · ${esc(c.cnc_software)}</span></div><div class="kb-facts"><span>X/Y/Z подтверждены</span><span>Револьвер: ${esc(caps.turret_positions)} позиций</span><span>Tailstock Jog: ${caps.tailstock_jog_control?'есть':'не подтвержден'}</span><span>MPF: ${m.release_policy?.automatic_mpf?'разрешён':'заблокирован до паспорта'}</span></div>`;docs.innerHTML=(documentData.items||[]).sort((a,b)=>a.priority-b.priority).map(d=>`<div class="kb-doc"><b>${esc(d.title)}</b><span>${esc(d.software||'')} · ${esc(d.applicability||'')}</span></div>`).join('');status.className='check-card good';status.textContent=`База готова: ${summary.counts.total_entries} записей, ${summary.counts.documents} источников`;run()}).catch(error=>{status.className='check-card warning';status.textContent=error.message});search.oninput=()=>{clearTimeout(timer);timer=setTimeout(run,180)};category.onchange=run}if(name==='libraries'){const results=document.getElementById('supportResults'),search=document.getElementById('supportSearch');const draw=()=>{const q=(search.value||'').toLowerCase();results.innerHTML=TOOL_LIBRARY.filter(x=>x.toLowerCase().includes(q)).map(x=>`<button class="support-item" data-pick-tool="${esc(x)}">${esc(x)}</button>`).join('')||'<p>Ничего не найдено</p>'};search.oninput=draw;draw();document.querySelectorAll('[data-pick-tool]').forEach(b=>b.onclick=()=>{if(!state.tools.length)defaultTools();state.tools[0][1]=b.dataset.pickTool;persist();alert('Инструмент добавлен в проект: '+b.dataset.pickTool)})}if(name==='calculators'){document.getElementById('calcBtn').onclick=()=>{const vc=+document.getElementById('calcVc').value,d=+document.getElementById('calcD').value,f=+document.getElementById('calcF').value;if(!(vc>0&&d>0&&f>=0))return alert('Проверьте значения');const n=Math.round(1000*vc/(Math.PI*d)),vf=Math.round(n*f);document.getElementById('calcResult').innerHTML=`${n.toLocaleString('ru-RU')} об/мин<br><small>${vf.toLocaleString('ru-RU')} мм/мин</small>`}}if(name==='settings'){const current=localStorage.getItem(THEME_KEY)||'auto';document.querySelectorAll('[data-theme-choice]').forEach(button=>{button.classList.toggle('active',button.dataset.themeChoice===current);button.onclick=()=>{document.querySelectorAll('[data-theme-choice]').forEach(x=>x.classList.remove('active'));button.classList.add('active');applyTheme(button.dataset.themeChoice)}});document.getElementById('settingsSave').onclick=()=>{localStorage.setItem('rozfood_autosave',document.getElementById('settingAutosave').checked?'true':'false');state.projectName=document.getElementById('settingProjectName').value.trim()||'Новый проект';persist();renderInspector();document.getElementById('supportModal').classList.remove('open')}}}
window.CNC_CAM_getInput=()=>{
  const operations=state.route.map((name,i)=>({id:`route-${i+1}`,name,tool:state.tools[i]?.[1]||null,speed:state.tools[i]?.[3]||null,feed:state.tools[i]?.[4]||null,ap:state.tools[i]?.[5]||null}));
  const maxDepth=state.tools.map(tool=>numeric(tool?.[5])).find(value=>value>0)??null;
  return {projectId:state.projectId,blankDiameter:numeric(state.fields.blankDiameter),blankLength:numeric(state.fields.overallLength),radialAllowance:Math.max(0,(numeric(state.stock.allowanceD)||0)/2),axialAllowance:Math.max(0,numeric(state.stock.allowanceL)||0),maxDepth,finishAllowance:0.2,coordinateSystem:{xMode:'diameter',zZero:'right_face'},setup:{clampSide:state.stock.clampSide||'left',clampDiameter:numeric(state.stock.clampDiameter),clampLength:numeric(state.stock.clampLength),protectClampZone:state.stock.protectClampZone!==false,processingOrder:state.stock.processingOrder||'from_clamp_to_free',visualMirror:state.stock.visualMirror!==false,baseReference:state.stock.baseReference||'clamp_face',confirmed:Boolean(state.stock.clampConfirmed)},contourPoints:state.contour.map(([x,z])=>({x,z})),operations,material:state.fields.material,geometry:state.geometry,afContour:state.afContour,features:state.camFeatures,machineSetup:state.machineSetup,postprocessor:state.postprocessor};
};
window.CNC3D_getData=window.CNC_CAM_getInput;
window.CNC_CAM_setSummary=summary=>{state.camSummary=summary;persist()};


function projectSnapshot(){return JSON.parse(JSON.stringify({...state,file:null,preview:null}))}
function replaceState(data,projectId=null){
  const fresh={step:0,done:Array(10).fill(false),file:null,preview:null,analysis:null,recognitionCrop:emptyRecognitionCrop(),fields:emptyFields(),dimensions:{overallLength:null,axialSegments:[],revision:1,source:"empty"},stock:defaultStock(),applicability:{thread:null,drilling:null,radialDrilling:null,af:null,millingPocket:null,cutoff:null},camRecognition:{},contour:[],geometry:emptyGeometry(),afContour:[],tools:[],route:[],camSummary:null,simulationReviewed:false,finalResult:null,finalizedAt:null,projectName:"Новый проект",projectId:null,...JSON.parse(JSON.stringify(DEFAULT_CAM_CONFIG))};
  Object.assign(state,fresh,data||{});ensureCamConfiguration();ensureStockSetup();ensureRecognitionCrop();ensureApplicability();if(isNotApplicable(state.fields.thread)){state.applicability.thread=false;clearCamFeature('threading')}if(isNotApplicable(state.fields.af)){state.applicability.af=false;clearCamFeature('millingAf')}state.file=null;state.preview=null;state.projectId=projectId??data?.projectId??null;
  if(!Array.isArray(state.done)||state.done.length!==10)state.done=Array(10).fill(false);ensureDimensionModel();syncDimensionsToFields();
  persist();render();
}
function fmtTime(ts){return new Date(Number(ts)*1000).toLocaleString('ru-RU')}
function ensureManagerModal(){
  let modal=document.getElementById('managerModal');if(modal)return modal;
  modal=document.createElement('div');modal.id='managerModal';modal.className='support-modal';
  modal.innerHTML='<div class="support-dialog manager-dialog"><div class="support-head"><h2 id="managerTitle"></h2><button id="managerClose" class="ghost">×</button></div><div id="managerBody"><div class="manager-loading">Загрузка…</div></div></div>';
  document.body.appendChild(modal);modal.querySelector('#managerClose').onclick=()=>modal.classList.remove('open');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};return modal;
}
async function openProjects(){
  const modal=ensureManagerModal(),body=modal.querySelector('#managerBody');modal.querySelector('#managerTitle').textContent='ПРОЕКТЫ';modal.classList.add('open');body.innerHTML='<div class="manager-loading">Загрузка проектов Railway…</div>';
  try{const r=await fetch('/api/projects');const items=await r.json();if(!r.ok)throw new Error(items.detail||'Не удалось загрузить проекты');
    body.innerHTML=`<div class="manager-toolbar"><input id="managerProjectName" value="${esc(state.projectName)}" placeholder="Название проекта"><button id="managerSaveProject" class="primary">${state.projectId?'СОХРАНИТЬ ИЗМЕНЕНИЯ':'СОЗДАТЬ И СОХРАНИТЬ'}</button></div><div class="manager-list">${items.length?items.map(x=>`<article class="manager-item"><div><b>${esc(x.name)}</b><small>Изменён: ${fmtTime(x.updated_at)}</small></div><div class="manager-actions"><button class="ghost" data-open-project="${x.id}">Открыть</button><button class="danger" data-delete-project="${x.id}">Удалить</button></div></article>`).join(''):'<div class="manager-empty">Сохранённых проектов пока нет</div>'}</div>`;
    body.querySelector('#managerSaveProject').onclick=saveCurrentProject;
    body.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>loadProject(+b.dataset.openProject));
    body.querySelectorAll('[data-delete-project]').forEach(b=>b.onclick=()=>deleteProject(+b.dataset.deleteProject));
  }catch(e){body.innerHTML=`<div class="check-card warning">${esc(e.message)}</div>`}
}
async function saveCurrentProject(){
  const name=document.getElementById('managerProjectName')?.value.trim()||state.projectName||'Новый проект';state.projectName=name;const payload={name,data:projectSnapshot()};
  const url=state.projectId?`/api/projects/${state.projectId}`:'/api/projects',method=state.projectId?'PUT':'POST';
  const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),j=await r.json();if(!r.ok)return alert(j.detail||'Ошибка сохранения');state.projectId=j.id;persist();renderInspector();openProjects();
}
async function loadProject(id){const r=await fetch(`/api/projects/${id}`),j=await r.json();if(!r.ok)return alert(j.detail||'Проект не найден');replaceState(j.data,j.id);ensureManagerModal().classList.remove('open')}
async function deleteProject(id){if(!confirm('Удалить сохранённый проект?'))return;const r=await fetch(`/api/projects/${id}`,{method:'DELETE'});if(!r.ok){const j=await r.json();return alert(j.detail||'Ошибка удаления')}if(state.projectId===id)state.projectId=null;openProjects()}
async function openHistory(){
  const modal=ensureManagerModal(),body=modal.querySelector('#managerBody');modal.querySelector('#managerTitle').textContent='ИСТОРИЯ АНАЛИЗОВ';modal.classList.add('open');body.innerHTML='<div class="manager-loading">Загрузка истории…</div>';
  try{const r=await fetch('/api/history?limit=100'),items=await r.json();if(!r.ok)throw new Error(items.detail||'Не удалось загрузить историю');
    body.innerHTML=`<div class="manager-list">${items.length?items.map(x=>`<article class="manager-item"><div><b>${esc(x.filename||'Без файла')}</b><small>${fmtTime(x.created_at)} · ${esc(x.model||'')}</small></div><div class="manager-actions"><button class="ghost" data-view-history="${x.id}">Открыть</button>${x.has_project?`<button class="primary" data-restore-history="${x.id}">Восстановить проект</button>`:''}<button class="danger" data-delete-history="${x.id}">Удалить</button></div></article>`).join(''):'<div class="manager-empty">История анализов пока пуста</div>'}</div>`;
    body.querySelectorAll('[data-view-history]').forEach(b=>b.onclick=()=>viewHistory(+b.dataset.viewHistory));body.querySelectorAll('[data-restore-history]').forEach(b=>b.onclick=()=>restoreHistory(+b.dataset.restoreHistory));body.querySelectorAll('[data-delete-history]').forEach(b=>b.onclick=()=>deleteHistory(+b.dataset.deleteHistory));
  }catch(e){body.innerHTML=`<div class="check-card warning">${esc(e.message)}</div>`}
}
async function viewHistory(id){const body=ensureManagerModal().querySelector('#managerBody'),r=await fetch(`/api/history/${id}`),j=await r.json();if(!r.ok)return alert(j.detail||'Запись не найдена');body.innerHTML=`<div class="history-detail"><button id="historyBack" class="ghost">← К списку</button><h3>${esc(j.filename||'Анализ')}</h3><div class="check-card"><b>Запрос</b><span>${esc(j.prompt||'')}</span></div><pre class="history-response">${esc(j.response||'')}</pre>${j.project?'<button id="historyRestore" class="primary">ВОССТАНОВИТЬ ПРОЕКТ ИЗ ЭТОГО АНАЛИЗА</button>':''}</div>`;body.querySelector('#historyBack').onclick=openHistory;if(j.project)body.querySelector('#historyRestore').onclick=()=>{replaceState(j.project,null);ensureManagerModal().classList.remove('open')}}
async function restoreHistory(id){const r=await fetch(`/api/history/${id}`),j=await r.json();if(!r.ok)return alert(j.detail||'Запись не найдена');if(!j.project)return alert('В этой записи нет снимка проекта');replaceState(j.project,null);ensureManagerModal().classList.remove('open')}
async function deleteHistory(id){if(!confirm('Удалить запись истории?'))return;const r=await fetch(`/api/history/${id}`,{method:'DELETE'});if(!r.ok){const j=await r.json();return alert(j.detail||'Ошибка удаления')}openHistory()}
const PROCESS_TEMPLATES=[
 {name:'Токарная ступенчатая деталь',mode:'turning',route:['Торцевание','Черновое наружное точение','Чистовое наружное точение','Фаска','Отрезка']},
 {name:'Фланец токарно-фрезерный',mode:'hybrid',route:['Торцевание','Черновая расточка','Чистовая расточка','Наружное точение','Сверление отверстий','Фрезерование/индексация C']},
 {name:'Резьбовая деталь с AF',mode:'hybrid',route:['Торцевание','Подготовка диаметра под резьбу','Фаска','Нарезание резьбы','Фрезерование AF','Контроль']}
];
function openTemplates(){const modal=ensureManagerModal(),body=modal.querySelector('#managerBody');modal.querySelector('#managerTitle').textContent='ШАБЛОНЫ ТЕХПРОЦЕССОВ';modal.classList.add('open');body.innerHTML=`<div class="template-grid">${PROCESS_TEMPLATES.map((t,i)=>`<article class="template-card"><h3>${esc(t.name)}</h3><ol>${t.route.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><button class="primary" data-apply-template="${i}">ИСПОЛЬЗОВАТЬ ШАБЛОН</button></article>`).join('')}</div>`;body.querySelectorAll('[data-apply-template]').forEach(b=>b.onclick=()=>{const t=PROCESS_TEMPLATES[+b.dataset.applyTemplate];state.fields.mode=t.mode;state.route=[...t.route];state.done[6]=false;resetDependents(5);persist();render();modal.classList.remove('open')})}


function showToast(message, kind='good') {
  let toast=document.getElementById('appToast');
  if(!toast){toast=document.createElement('div');toast.id='appToast';toast.className='app-toast';document.body.appendChild(toast)}
  toast.className=`app-toast ${kind}`;toast.textContent=message;toast.classList.add('show');
  clearTimeout(showToast._timer);showToast._timer=setTimeout(()=>toast.classList.remove('show'),2600);
}
function openNewProjectDialog(){
  const modal=ensureManagerModal(),body=modal.querySelector('#managerBody');
  modal.querySelector('#managerTitle').textContent='НОВЫЙ ПРОЕКТ';
  body.innerHTML=`<div class="new-project-dialog"><p class="muted">Текущий несохранённый проект будет очищен. Сохранённые проекты и история Railway останутся.</p><div class="field-row"><label>Название проекта</label><input id="newProjectName" value="Новый проект" maxlength="80" autocomplete="off"></div><div class="action-row"><button id="newProjectCancel" class="ghost">ОТМЕНА</button><button id="newProjectCreate" class="primary">СОЗДАТЬ НОВЫЙ ПРОЕКТ</button></div><div id="newProjectStatus" class="manager-loading" hidden></div></div>`;
  modal.classList.add('open');
  const input=body.querySelector('#newProjectName');setTimeout(()=>{input.focus();input.select()},0);
  body.querySelector('#newProjectCancel').onclick=()=>modal.classList.remove('open');
  body.querySelector('#newProjectCreate').onclick=()=>createNewProjectFromDialog();
  input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();createNewProjectFromDialog()}};
}
async function createNewProjectFromDialog(){
  const modal=ensureManagerModal(),body=modal.querySelector('#managerBody'),input=body.querySelector('#newProjectName'),status=body.querySelector('#newProjectStatus'),button=body.querySelector('#newProjectCreate');
  const name=(input?.value||'').trim()||'Новый проект';
  button.disabled=true;status.hidden=false;status.textContent='Создание проекта…';
  replaceState({projectName:name},null);
  try{
    const r=await fetch('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,data:projectSnapshot()})});
    const j=await r.json();
    if(!r.ok)throw new Error(j.detail||'Не удалось сохранить проект');
    state.projectId=j.id;persist();renderInspector();
    modal.classList.remove('open');showToast(`Проект «${name}» создан`);
  }catch(error){
    modal.classList.remove('open');showToast(`Создан локальный проект «${name}». Railway: ${error.message}`,'warning');
  }
}

function activateSupportButton(button){
  document.querySelectorAll('[data-support]').forEach(b=>b.classList.toggle('active',b===button));
  openSupport(button.dataset.support);
}
function bindPersistentNavigation(){
  document.querySelectorAll('[data-support]').forEach(button=>{
    button.type='button';
    button.onclick=(event)=>{event.preventDefault();event.stopPropagation();activateSupportButton(button)};
    button.onkeydown=(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();activateSupportButton(button)}};
  });
  document.querySelectorAll('[data-nav]').forEach(button=>{
    button.type='button';
    button.onclick=()=>{
      const action=button.dataset.nav;
      if(action==='new'){openNewProjectDialog();return;}
      if(action==='history'){openHistory();return;}
      if(action==='projects'){openProjects();return;}
      if(action==='templates'){openTemplates();return;}
    };
  });
  const passport=document.querySelector('.machine-card button');
  if(passport)passport.onclick=()=>openSupport('knowledge');
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-step-jump]');
  if(b){let i=+b.dataset.stepJump;if(i===0||state.done[i-1]||state.done[i]){state.step=i;render()}}
});
$('#themeBtn').onclick=cycleTheme;
bindPersistentNavigation();
render();


// v4.2.3 Responsive drawer controls for phone and tablet. Layout selection is based only on viewport width.
function isResponsiveDrawerViewport(){return window.matchMedia('(max-width:1199px)').matches}
function closeResponsivePanels(){
  document.body.classList.remove('tablet-sidebar-open','tablet-inspector-open');
  document.getElementById('tabletMenuBtn')?.setAttribute('aria-expanded','false');
  document.getElementById('tabletInspectorBtn')?.setAttribute('aria-expanded','false');
}
function toggleResponsivePanel(kind){
  if(!isResponsiveDrawerViewport())return;
  const sidebar=kind==='sidebar';
  document.body.classList.toggle('tablet-sidebar-open',sidebar&&!document.body.classList.contains('tablet-sidebar-open'));
  document.body.classList.toggle('tablet-inspector-open',!sidebar&&!document.body.classList.contains('tablet-inspector-open'));
  document.getElementById('tabletMenuBtn')?.setAttribute('aria-expanded',String(document.body.classList.contains('tablet-sidebar-open')));
  document.getElementById('tabletInspectorBtn')?.setAttribute('aria-expanded',String(document.body.classList.contains('tablet-inspector-open')));
}
document.getElementById('tabletMenuBtn')?.addEventListener('click',()=>toggleResponsivePanel('sidebar'));
document.getElementById('tabletInspectorBtn')?.addEventListener('click',()=>toggleResponsivePanel('inspector'));
document.getElementById('tabletBackdrop')?.addEventListener('click',closeResponsivePanels);
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeResponsivePanels()});
document.querySelectorAll('#sidebar button').forEach(button=>button.addEventListener('click',()=>{if(isResponsiveDrawerViewport())setTimeout(closeResponsivePanels,0)}));
window.addEventListener('resize',()=>{if(!isResponsiveDrawerViewport())closeResponsivePanels()});
window.addEventListener('orientationchange',closeResponsivePanels);
